const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define cities as points with buffers
  const beijing = ee.Geometry.Point([116.4074, 39.9042]).buffer(20000);
  const chongqing = ee.Geometry.Point([106.5516, 29.5630]).buffer(20000);
  const wuhan = ee.Geometry.Point([114.2734, 30.5833]).buffer(20000);

  const cities = [
    {name: 'Beijing', geom: beijing},
    {name: 'Chongqing', geom: chongqing},
    {name: 'Wuhan', geom: wuhan}
  ];

  // Time periods
  const janPeriod = ['2020-01-01', '2020-01-20'];
  const febPeriod = ['2020-02-10', '2020-02-25'];

  // Sentinel-5P NO2 collection
  const no2Collection = 'COPERNICUS/S5P/OFFL/L3_NO2';
  const no2Band = 'tropospheric_NO2_column_number_density';

  const results = [];

  for (const city of cities) {
    // Get collections for both periods
    const janCol = ee.ImageCollection(no2Collection)
      .filterDate(janPeriod[0], janPeriod[1])
      .filterBounds(city.geom)
      .select(no2Band);

    const febCol = ee.ImageCollection(no2Collection)
      .filterDate(febPeriod[0], febPeriod[1])
      .filterBounds(city.geom)
      .select(no2Band);

    const janSize = janCol.size().getInfo();
    const febSize = febCol.size().getInfo();

    // Check for empty collections
    if (janSize === 0 || febSize === 0) {
      console.log(`${city.name}: Empty collection (Jan: ${janSize}, Feb: ${febSize})`);
      console.log('<answer>C1</answer>');
      return;
    }

    // Compute mean NO2 for each period
    const janMean = janCol.mean();
    const febMean = febCol.mean();

    // Get pixel counts and values
    const janStats = janMean.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
      geometry: city.geom,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const febStats = febMean.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
      geometry: city.geom,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const janValue = janStats[no2Band + '_mean'];
    const febValue = febStats[no2Band + '_mean'];
    const janCount = janStats[no2Band + '_count'];
    const febCount = febStats[no2Band + '_count'];

    // Check for no valid pixels
    if (janCount === 0 || febCount === 0) {
      console.log(`${city.name}: No valid pixels (Jan: ${janCount}, Feb: ${febCount})`);
      console.log('<answer>C2</answer>');
      return;
    }

    // Validate values are reasonable (NO2 should be positive and typically < 1e-4 mol/m²)
    if (janValue === null || febValue === null || 
        janValue < 0 || febValue < 0 || 
        janValue > 1e-3 || febValue > 1e-3) {
      console.log(`${city.name}: Invalid values (Jan: ${janValue}, Feb: ${febValue})`);
      console.log('<answer>C3</answer>');
      return;
    }

    results.push({
      name: city.name,
      janValue: janValue,
      febValue: febValue,
      decreased: febValue < janValue
    });

    console.log(`${city.name}: Jan ${janValue.toExponential(2)} (px:${janCount}), Feb ${febValue.toExponential(2)} (px:${febCount})`);
  }

  // Check if all cities show decrease
  const allDecreased = results.every(r => r.decreased);
  console.log(`All decreased: ${allDecreased}`);

  if (allDecreased) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
